mapper.select:
SELECT cap.*, cap.issue_amount-nvl(apr.due_amount,0)-nvl(pcd.cash_principal,0)-nvl(caps.subscribe_amount,0) surplus_amount, ( SELECT su.description FROM sys_user su WHERE su.user_id = cap.user_id ) AS create_person, ( SELECT meaning value_name FROM sys_code_value_b_v v WHERE v.CODE = 'ABS.PRODUCT_STATUS' AND v.code_value = cap.product_status ) product_status_n FROM ct_abs_product cap left join sys_user su on su.user_id = cap.user_id left join ( SELECT pr.product_id, SUM(pr.due_amount) due_amount FROM ct_abs_product_repayment pr WHERE pr.cf_item=301 GROUP BY pr.product_id ) apr ON apr.product_id=cap.product_id left join ( SELECT cd.product_id, SUM(cd.cash_principal) cash_principal FROM ct_abs_product_cash_detail cd join ct_abs_product_collection capc on capc.collection_id=cd.collection_id and capc.data_class='NORMAL' GROUP BY cd.product_id ) pcd ON pcd.product_id=cap.product_id left join ( SELECT ps.product_id, SUM(ps.subscribe_amount) subscribe_amount FROM ct_abs_product_subscribe ps WHERE ps.subscribe_status='CONFIRM' AND ps.subscribe_type='SELF_HOLDING_SUBSCRIPTION' GROUP BY ps.product_id ) caps ON caps.product_id=cap.product_id
and cap.product_number like concat('%',concat(#{productNumber},'%'))
and cap.product_name like concat('%',concat(#{productName},'%'))
and cap.product_status = #{productStatus}
and su.description like concat('%',concat(#{createPerson},'%'))
and cap.product_name like concat('%',concat(#{projectName},'%'))
and cap.product_date >= #{startDate}
and cap.product_date <= #{endDate}
and cap.issue_amount >= #{amtFrom}
and cap.issue_amount <= #{amtTo}
order by creation_date desc

SELECT cap.*, cap.publish_number as publish_number_n, subscribe_info.abs_company_name as subscribe_main_name, subscribe_info.BANK_ACCOUNT_NAME as SUBSCRIBE_ACCOUNT_NAME, subscribe_info.BANK_ACCOUNT_NUM as SUBSCRIBE_ACCOUNT_NUM, subscribe_info.BANK_BRANCH_NAME as SUBSCRIBE_BRANCH_NAME, (select s.MEANING from sys_code_value_b_v s where s.CODE_VALUE = cap.trading_palce and s.code ='BOND_TRADING_PLACE') trading_palce_n, (select s.MEANING from sys_code_value_b_v s where s.CODE_VALUE = cap.PUBLISH_METHOD and s.code ='BOND_ISSUANCE_METHOD') publish_method_n, (select s.MEANING from sys_code_value_b_v s where s.CODE_VALUE = cap.TABLE_FLAG and s.code = 'SYS.YES_NO') table_flag_n, (select s.MEANING from sys_code_value_b_v s where s.CODE_VALUE = cap.SUBJECT_GRADE and s.code = 'ABS.SUBJECT_RATE') subject_grade_n, (select s.MEANING from sys_code_value_b_v s where s.CODE_VALUE = cap.SUBSCRIBE_FLAG and s.code = 'SYS.YES_NO') subscribe_flag_n, (select s.MEANING from sys_code_value_b_v s where s.CODE_VALUE = cap.INTEREST_STANDARD_DAYS and s.code = 'ABS_PRODUCT_STANDAR_DAYS') interest_standard_days_n, (select s.MEANING from sys_code_value_b_v s where s.CODE_VALUE = cap.RATE_METHOD and s.code = 'ABS.INTEREST_BEARING_METHOD') rate_method_n, (select s.MEANING from sys_code_value_b_v s where s.CODE_VALUE = cap.PAY_CAPITAL_FREQUENCY and s.code = 'ABS_PRODUCT_PAY_CAPITAL') pay_capital_frequency_n, (select s.MEANING from sys_code_value_b_v s where s.CODE_VALUE = cap.PAY_INTEREST_FREQUENCY and s.code = 'ABS_PRODUCT_PAY_INTEREST') pay_interest_frequency_n, (select s.MEANING from sys_code_value_b_v s where s.CODE_VALUE = cap.PAY_METHOD and s.code ='ABS.REPAYMENT_METHOD') pay_method_n, (select s.MEANING from sys_code_value_b_v s where s.CODE_VALUE = cap.product_currency_code and s.code = 'CHS.CURRENCY_TYPE') product_currency_code_n, (select s.MEANING from sys_code_value_b_v s where s.CODE_VALUE = cap.CASH_PERIOD and s.code = 'ABS_PRODUCT_CASH_PERIOD') cash_period_n, cap.issue_amount - nvl( apr.due_amount, 0 ) - nvl( pcd.cash_principal, 0 ) - nvl( caps.subscribe_amount, 0 ) AS surplus_amount, ( SELECT su.description FROM sys_user su WHERE su.user_id = cap.user_id ) AS create_person, t1.asset_contract_count, t1.collected_due_amount, t1.collected_principal, t1.collected_interest, t1.collected_other_amount, t1.asset_rent_count, caap.BASE_DATE_FROM, caap.BASE_DATE_TO, ( SELECT s.MEANING FROM sys_code_value_b_v s WHERE s.CODE_VALUE = cap.IF_RELATE_PACK AND s.CODE = 'SYS.YES_NO' ) AS if_relate_pack_n, caap.base_date, caap.pack_number AS pack_id_n, ( SELECT caj.other_project_type FROM ct_abs_project caj WHERE caj.project_id = cap.project_id ) other_project_type, ( SELECT caj.project_number FROM ct_abs_project caj WHERE caj.project_id = cap.project_id ) project_number, ( SELECT caj.project_english_type FROM ct_abs_project caj WHERE caj.project_id = cap.project_id ) project_english_type, fou.unit_name, company.company_full_name AS company_name, capj.base_asset_type, v1.meaning base_asset_type_n, (SELECT cfp.plan_number FROM cap_financing_plan_ln capl JOIN cap_financing_plan cfp ON capl.plan_id = cfp.plan_id LEFT JOIN sys_user su ON su.user_id = cfp.user_id WHERE capl.finance_plan_line_id = cap.finance_plan_line_id AND capl.plan_type = 'FINANCE_PLAN' AND capl.finance_status in ('PARTIAL_EXECUTED', 'UNEXECUTED') AND cfp.data_class = 'NORMAL' AND cfp.confirm_status = 'FULL') finance_plan_line_id_n FROM ct_abs_product cap LEFT JOIN (select caba.source_key,caba.abs_company_name,caba.BANK_ACCOUNT_NAME,caba.BANK_ACCOUNT_NUM,caba.BANK_BRANCH_NAME from ct_abs_bank_account caba where caba.account_source_type = 'OUR_ACCOUNT' and caba.source_type = 'ABS_PRODUCT' group by caba.source_key,caba.account_source_type HAVING COUNT(0) = 1) subscribe_info on subscribe_info.source_key = cap.product_id LEFT JOIN ( SELECT pr.product_id, SUM( pr.due_amount ) AS due_amount FROM ct_abs_product_repayment pr WHERE pr.cf_item = 301 GROUP BY pr.product_id ) apr ON apr.product_id = cap.product_id LEFT JOIN ( SELECT cd.product_id, SUM( cd.cash_principal ) AS cash_principal FROM ct_abs_product_cash_detail cd JOIN ct_abs_product_collection capc ON capc.collection_id = cd.collection_id AND capc.data_class = 'NORMAL' GROUP BY cd.product_id ) pcd ON pcd.product_id = cap.product_id LEFT JOIN ( SELECT ps.product_id, SUM( ps.subscribe_amount ) AS subscribe_amount FROM ct_abs_product_subscribe ps WHERE ps.subscribe_status = 'CONFIRM' AND ps.subscribe_type = 'SELF_HOLDING_SUBSCRIPTION' GROUP BY ps.product_id ) caps ON caps.product_id = cap.product_id LEFT JOIN ( SELECT PACK.PACK_ID, PACK.PACK_NUMBER pack_id_n, PACK.BASE_DATE_FROM, PACK.BASE_DATE_TO, COUNT(DISTINCT PACK.CONTRACT_ID) AS asset_contract_count, COUNT(DISTINCT PACK.SAL_BP_NAME) AS asset_rent_count, SUM(UNCOLLECTED_PRINCIPAL + UNCOLLECTED_INTEREST + UNCOLLECTED_OTHER_AMOUNT) AS collected_due_amount , SUM(PACK.UNCOLLECTED_PRINCIPAL) AS collected_principal, SUM(PACK.UNCOLLECTED_INTEREST) AS collected_interest, SUM(PACK.UNCOLLECTED_OTHER_AMOUNT) AS collected_other_amount FROM ( SELECT caap.PACKAGE_ID, caap.PACK_ID, caap.CONTRACT_ID, cap.PACK_NUMBER, cap.BASE_DATE_FROM, cap.BASE_DATE_TO, cc.CONTRACT_NUMBER, cc.CONTRACT_NAME, SAL_BP_NAME.SAL_BP_NAME, BUY_BP_NAME.BUY_BP_NAME, nvl( ( SELECT SUM( nvl( CA.DUE_AMOUNT, 0 ) - nvl( CA.RECEIVED_AMOUNT, 0 ) ) FROM CON_CONTRACT_CASHFLOW CA WHERE CA.CONTRACT_ID = CAAP.CONTRACT_ID AND CA.CF_STATUS = 'RELEASE' AND CA.CF_ITEM = 52 ), 0 ) - nvl( ( SELECT nvl( SUM( CA.DUE_AMOUNT ), 0 ) - nvl( SUM( CA.RECEIVED_AMOUNT ), 0 ) FROM CON_CONTRACT_CASHFLOW CA WHERE CA.CF_ITEM = 14 AND CA.CF_STATUS = 'RELEASE' AND CA.CONTRACT_ID = CAAP.CONTRACT_ID ), 0 ) AS SURPLUS_DEPOSIT_AMOUNT, nvl( ( SELECT SUM( nvl( ccc.PRINCIPAL, 0 ) - nvl( ccc.RECEIVED_PRINCIPAL, 0 ) ) FROM con_contract_cashflow ccc WHERE ccc.CONTRACT_ID = cc.CONTRACT_ID AND ccc.CF_STATUS = 'RELEASE' AND ccc.CF_ITEM = 1 AND ccc.DUE_DATE >= caap.PACK_DATE_FROM AND ccc.DUE_DATE <= caap.PACK_DATE_TO AND caap.PACK_DATE_FROM IS NOT NULL AND caap.PACK_DATE_TO IS NOT NULL ), 0 ) AS UNCOLLECTED_PRINCIPAL, nvl( ( SELECT SUM( nvl( ccc.INTEREST, 0 ) - nvl( ccc.RECEIVED_INTEREST, 0 ) ) FROM con_contract_cashflow ccc WHERE ccc.CONTRACT_ID = cc.CONTRACT_ID AND ccc.CF_STATUS = 'RELEASE' AND ccc.CF_ITEM = 1 AND ccc.DUE_DATE >= caap.PACK_DATE_FROM AND ccc.DUE_DATE <= caap.PACK_DATE_TO AND caap.PACK_DATE_FROM IS NOT NULL AND caap.PACK_DATE_TO IS NOT NULL ), 0 ) AS UNCOLLECTED_INTEREST, nvl( ( SELECT SUM( nvl( ccc.DUE_AMOUNT, 0 ) - nvl( ccc.RECEIVED_PRINCIPAL, 0 ) ) FROM con_contract_cashflow ccc WHERE ccc.CONTRACT_ID = cc.CONTRACT_ID AND ccc.CF_STATUS = 'RELEASE' AND ccc.CF_DIRECTION = 'INFLOW' AND CCC.CF_ITEM NOT IN ( 1, 51 ) AND ccc.DUE_DATE >= caap.PACK_DATE_FROM AND ccc.DUE_DATE <= caap.PACK_DATE_TO AND caap.PACK_DATE_FROM IS NOT NULL AND caap.PACK_DATE_TO IS NOT NULL ), 0 ) AS UNCOLLECTED_OTHER_AMOUNT, ( SELECT nvl( SUM( CASE WHEN CA.OVERDUE_STATUS = 'Y' THEN 1 ELSE 0 END ), 0 ) FROM CON_CONTRACT_CASHFLOW CA WHERE CC.CONTRACT_ID = CA.CONTRACT_ID AND CA.CF_STATUS = 'RELEASE' AND CA.DUE_DATE >= caap.PACK_DATE_FROM AND CA.DUE_DATE <= caap.PACK_DATE_TO AND caap.PACK_DATE_FROM IS NOT NULL AND caap.PACK_DATE_TO IS NOT NULL ) AS OVERDUE_STATUS FROM ct_abs_assets_package caap LEFT JOIN ct_abs_assets_pack cap ON caap.pack_id = cap.pack_id LEFT JOIN con_contract cc ON caap.CONTRACT_ID = cc.CONTRACT_ID LEFT JOIN ( SELECT PB.PROJECT_ID, wm_concat( BM.BP_NAME ) AS SAL_BP_NAME FROM PRJ_PROJECT_BP PB JOIN HLS_BP_MASTER BM ON PB.BP_ID = BM.BP_ID WHERE PB.BP_TYPE = 'TENANT' GROUP BY PB.PROJECT_ID ) SAL_BP_NAME ON SAL_BP_NAME.PROJECT_ID = CC.PROJECT_ID LEFT JOIN ( SELECT PB.PROJECT_ID, wm_concat( BM.BP_NAME ) AS BUY_BP_NAME FROM PRJ_PROJECT_BP PB JOIN HLS_BP_MASTER BM ON PB.BP_ID = BM.BP_ID WHERE PB.BP_TYPE = 'TENANT_SEC' GROUP BY PB.PROJECT_ID ) BUY_BP_NAME ON BUY_BP_NAME.PROJECT_ID = CC.PROJECT_ID ) PACK WHERE 1 = 1 GROUP BY PACK.PACK_ID
) t1 ON t1.pack_id = cap.pack_id LEFT JOIN ct_abs_assets_pack caap ON cap.pack_id = caap.pack_id LEFT JOIN fnd_org_unit fou ON fou.unit_id = cap.unit_id LEFT JOIN fnd_company company ON company.company_id = cap.company_id LEFT JOIN ct_abs_project capj on capj.project_id = cap.project_id LEFT JOIN sys_code_value_b_v v1 on v1.code = 'ABS.BASE_ASSET_TYPE' AND v1.code_value=capj.base_asset_type
and cap.product_number like concat('%',concat(#{productNumber},'%'))
and cap.product_name like concat('%',concat(#{productName},'%'))
and cap.product_id = #{productId}
and cap.business_type = #{businessType}
and ( cap.product_number like concat('%',concat(#{condition},'%')) or cap.product_name like concat('%',concat(#{condition},'%')))
order by cap.product_id desc

SELECT cap2.project_number, cap2.project_name, cap2.project_short_name, cap2.project_english_type, cap2.base_asset_type, cap2.other_project_type, cri.status change_status, cap.*, caap.pack_number, caap.base_date, pack.asset_contract_count, rent.asset_rent_count, pack.uncollected_due_amount, pack.uncollected_principal, pack.uncollected_interest, pack.collected_due_amount, pack.collected_principal, pack.collected_interest, capq.PUBLISH_DATE, capq.quotation_id, capq.measure_type, capq.due_date, capq.withdraw_end_date, capq.loan_term, capq.due_amount, capq.exchange_rate, capq.convert_currency, capq.convert_begin_principal_amount, capq.int_rate_type, capq.base_rate_type, capq.base_rate, capq.floating_way, capq.floating_way_range, capq.int_rate, capq.first_rate, capq.calc_interest_year_days, capq.interest_cycle, capq.interest_calc_method, capq.interest_month, capq.interest_payment_date, capq.loan_times, capq.interest_calc_date, capq.comperhensive_financing_cost, capq.xirr, capq.tax_rate, capq.floating_range_method, capq.floating_range_method_remark, capq.rate_change_after, capq.rate_change_date, capq.calc_interest_year_days_after, nvl((select nvl(sum(cbpr.planned_due_amount),0) from ct_abs_product_repayment cbpr where cbpr.product_id = cap.product_id and cbpr.cf_item=302 ),0) interest_sum, nvl((select sum(round(cbpr.planned_due_amount*nvl(cbpr.exchange_rate,1),2)) from ct_abs_product_repayment cbpr where cbpr.product_id = cap.product_id and cbpr.cf_item=301 ),0) convert_pay_principal_amount, nvl((select sum(round(cbpr.planned_due_amount*nvl(cbpr.exchange_rate,1),2)) from ct_abs_product_repayment cbpr where cbpr.product_id = cap.product_id and cbpr.cf_item=302 ),0) convert_pay_interest_amount, ( SELECT fc.company_full_name FROM fnd_company fc WHERE fc.company_id = cap.company_id ) AS company_name, ( SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = cap.unit_id ) AS unit_name, ( SELECT su.description FROM sys_user su WHERE su.user_id = cap.user_id ) AS create_person, cfp.plan_number, cfp.plan_name, cap.issue_amount-nvl(capr.receipt_amount,0) issue_surplus_amount FROM ct_abs_product cap join ct_abs_project cap2 on cap.project_id = cap2.project_id left join cap_financing_plan_ln cfpl on cfpl.finance_plan_line_id=cap.finance_plan_line_id left join cap_financing_plan cfp on cfp.plan_id=cfpl.plan_id left join ct_abs_product_quotation capq on capq.product_id=cap.product_id left join change_req_info cri on cri.change_req_id=cap.change_req_id left join ct_abs_assets_pack caap on caap.pack_id=cap.pack_id left join pack on pack.pack_id=caap.pack_id left join rent on rent.pack_id=caap.pack_id left join ( SELECT pr.product_id, SUM(pr.receipt_amount) receipt_amount FROM ct_abs_product_receipt pr GROUP BY pr.product_id ) capr ON capr.product_id=cap.product_id
cap.company_id = #{request.companyId}
and cap.product_number like concat('%',concat(#{productNumber},'%'))
and cap.product_name like concat('%',concat(#{productName},'%'))
and cap.product_id = #{productId}
and cap.data_class = 'NORMAL'
and cap.business_type = #{businessType}
and ( cap.product_number like concat('%',concat(#{condition},'%')) or cap.product_name like concat('%',concat(#{condition},'%')))
order by cap.product_id desc

select a.issue_amount-(select sum(SUBSCRIBE_AMOUNT) from CT_ABS_PRODUCT_SUBSCRIBE a where a.SUBSCRIBE_TYPE='SELF_HOLDING_SUBSCRIPTION') product_income_amount
from ct_abs_product a
where a.product_id=#{productId}
